package com.monitoring.agent

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantLock
import java.util.concurrent.CopyOnWriteArrayList

data class TenantContext(val tenantId: String, val isolationLevel: Int)
data class LogEntry(val tenantId: String, val message: String, val timestamp: Long)

interface LogProcessor {
    fun process(entry: LogEntry, context: TenantContext): Boolean
}

class TenantIsolationGuard {
    private val tenantLocks = ConcurrentHashMap<String, ReentrantLock>()
    private val activeSessions = ConcurrentHashMap<String, MutableList<String>>()

    fun acquireTenantLock(tenantId: String): ReentrantLock {
        return tenantLocks.computeIfAbsent(tenantId) { ReentrantLock(true) }
    }

    fun registerSession(tenantId: String, sessionId: String) {
        activeSessions.computeIfAbsent(tenantId) { CopyOnWriteArrayList() }.add(sessionId)
    }

    fun getActiveSessions(tenantId: String): List<String> {
        return activeSessions[tenantId] ?: emptyList()
    }
}

class AuditTrail {
    private val entries = ConcurrentHashMap<String, MutableList<LogEntry>>()

    fun record(entry: LogEntry) {
        entries.computeIfAbsent(entry.tenantId) { CopyOnWriteArrayList() }.add(entry)
    }

    fun getEntriesForTenant(tenantId: String): List<LogEntry> {
        return entries[tenantId] ?: emptyList()
    }
}

class MonitoringAgent(
    private val guard: TenantIsolationGuard,
    private val audit: AuditTrail
) {
    private val processors = CopyOnWriteArrayList<LogProcessor>()
    private val tenantBuffers = ConcurrentHashMap<String, ArrayDeque<LogEntry>>()
    private val flushCallbacks = ConcurrentHashMap<String, () -> Unit>()

    fun registerProcessor(processor: LogProcessor) {
        processors.add(processor)
    }

    fun registerFlushCallback(tenantId: String, callback: () -> Unit) {
        flushCallbacks[tenantId] = callback
    }

    fun ingest(entry: LogEntry, context: TenantContext): Boolean {
        val lock = guard.acquireTenantLock(context.tenantId)
        lock.lock()
        try {
            if (context.tenantId != entry.tenantId) {
                return false
            }
            val buffer = tenantBuffers.computeIfAbsent(context.tenantId) { ArrayDeque(64) }
            buffer.addLast(entry)

            // Process through registered processors
            for (processor in processors) {
                if (!processor.process(entry, context)) {
                    buffer.removeLast()
                    return false
                }
            }

            audit.record(entry)

            // Flush if buffer exceeds threshold
            if (buffer.size >= context.isolationLevel) {
                flushBuffer(context.tenantId, lock)
            }

            return true
        } finally {
            if (lock.isHeldByCurrentThread) {
                lock.unlock()
            }
        }
    }

    private fun flushBuffer(tenantId: String, heldLock: ReentrantLock) {
        val buffer = tenantBuffers[tenantId] ?: return
        val snapshot = buffer.toList()
        buffer.clear()

        // Release lock before callback to prevent deadlock with external systems
        heldLock.unlock()

        // Invoke flush callback - this executes OUTSIDE the tenant lock
        flushCallbacks[tenantId]?.invoke()

        // Re-acquire for the finally block expectation
        heldLock.lock()
    }

    fun getTenantBufferSize(tenantId: String): Int {
        val lock = guard.acquireTenantLock(tenantId)
        lock.lock()
        try {
            return tenantBuffers[tenantId]?.size ?: 0
        } finally {
            lock.unlock()
        }
    }

    fun drainTenant(tenantId: String): List<LogEntry> {
        val lock = guard.acquireTenantLock(tenantId)
        lock.lock()
        try {
            val buffer = tenantBuffers[tenantId] ?: return emptyList()
            val result = buffer.toList()
            buffer.clear()
            return result
        } finally {
            lock.unlock()
        }
    }
}

// Example usage demonstrating the cross-tenant attack vector
fun main() {
    val guard = TenantIsolationGuard()
    val audit = AuditTrail()
    val agent = MonitoringAgent(guard, audit)

    // Malicious processor that exploits the reentrancy window
    val maliciousProcessor = object : LogProcessor {
        override fun process(entry: LogEntry, context: TenantContext): Boolean {
            // During the flush callback window, inject into another tenant's buffer
            return true
        }
    }
    agent.registerProcessor(maliciousProcessor)

    // Register a flush callback that re-enters the agent for a DIFFERENT tenant
    agent.registerFlushCallback("tenant-A") {
        // This executes while tenant-A's lock is RELEASED
        // An attacker can now call ingest for tenant-A with manipulated data
        val spoofedEntry = LogEntry("tenant-A", "INJECTED_BY_ATTACKER", System.currentTimeMillis())
        val spoofedContext = TenantContext("tenant-A", isolationLevel = 100)
        agent.ingest(spoofedEntry, spoofedContext)
    }

    // Normal operation triggers the vulnerability
    val ctx = TenantContext("tenant-A", isolationLevel = 1)
    agent.ingest(LogEntry("tenant-A", "legitimate log", System.currentTimeMillis()), ctx)

    println("Audit trail: ${audit.getEntriesForTenant("tenant-A").map { it.message }}")
}
